# Solaria process placement prelude (ADR 0014). Generated by Solaria; don't
# edit. The launcher calls clone(), then isolate() before anything else:
# clone() fetches the repositories the run works on, and isolate() builds
# the environment the run gets from isolation.json and creates the run's
# scratch directory. Nothing from the caller's environment reaches the run
# unless isolation.json names it.
import base64
import json
import os
import shutil
import subprocess
import sys
import tempfile
import urllib.parse

WIN = os.name == "nt"


def _lookup(env, name):
    """Read a variable the way the OS does: case-insensitively on Windows."""
    if not WIN:
        return env.get(name)
    want = name.upper()
    for k, v in env.items():
        if k.upper() == want:
            return v
    return None


def parse_dotenv(text):
    """Read a dotenv file as Solaria does (internal/secrets)."""
    out = {}
    for n, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if line == "" or line.startswith("#"):
            continue
        line = line.removeprefix("export ")
        name, eq, value = line.partition("=")
        name = name.strip()
        if not eq or name == "":
            raise ValueError(f"line {n}: want NAME=value")
        value = value.strip()
        if len(value) >= 2 and value[0] == "'" and value[-1] == "'":
            value = value[1:-1]
        elif len(value) >= 2 and value[0] == '"' and value[-1] == '"':
            try:
                value = json.loads(value)
            except json.JSONDecodeError as err:
                raise ValueError(f"line {n}: {err}") from None
        else:
            i = value.find(" #")
            if i >= 0:
                value = value[:i].strip()
        out[name] = value
    return out


def _secret_source(spec, caller):
    """Return where secrets come from: the dotenv file, or the caller's
    environment."""
    if not spec.get("dotenv"):
        return caller, "the environment variables"
    try:
        with open(spec["dotenv"], encoding="utf-8") as f:
            text = f.read()
    except FileNotFoundError:
        text = ""
    try:
        return parse_dotenv(text), spec["dotenv"]
    except ValueError as err:
        raise RuntimeError(f"{spec['dotenv']}: {err}") from None


def clone(spec, workspace):
    """Clone the repositories isolation.json lists into repositories/<name>
    in workspace (ADR 0017). git gets a scratch HOME and no system
    configuration, so none of the caller's git setup applies, and a
    repository's token reaches it only as an HTTP header for that
    repository's host: never in its arguments, the URL or its output, and
    never in the run's environment."""
    repos = spec.get("repositories") or []
    if not repos:
        return
    caller = dict(os.environ)
    values, where = _secret_source(spec, caller)
    base = {"GIT_CONFIG_NOSYSTEM": "1", "GIT_TERMINAL_PROMPT": "0"}
    for name in [*spec["pass"], "PATH", "PATHEXT", "SYSTEMROOT"]:
        v = _lookup(caller, name)
        if v and name != "ANTHROPIC_API_KEY":
            base[name] = v
    home = tempfile.mkdtemp(prefix="solaria-clone-")
    try:
        for r in repos:
            dest = os.path.join(workspace, "repositories", r["name"])
            if os.path.lexists(dest):
                raise RuntimeError(
                    f"repositories/{r['name']} already exists in the workspace; "
                    "remove it, or start the run in a fresh workspace"
                )
            env = {**base, "HOME": home, "USERPROFILE": home}
            if r.get("secretRef"):
                token = _lookup(values, r["secretRef"])
                if not token:
                    raise RuntimeError(f"secret not set in {where}: {r['secretRef']}, for repository {r['name']}")
                u = urllib.parse.urlsplit(r["url"])
                basic = base64.b64encode(f"x-access-token:{token}".encode()).decode()
                env["GIT_CONFIG_COUNT"] = "1"
                env["GIT_CONFIG_KEY_0"] = f"http.{u.scheme}://{u.netloc}/.extraHeader"
                env["GIT_CONFIG_VALUE_0"] = "Authorization: Basic " + basic
            args = ["git", "clone", "--quiet"]
            if r.get("depth"):
                args += ["--depth", str(r["depth"])]
            if r.get("ref"):
                args += ["--branch", r["ref"]]
            args += ["--", r["url"], dest]
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            git = shutil.which("git", path=env.get("PATH", ""))
            if git is None:
                raise RuntimeError(f"can't run git to clone repository {r['name']}: not found on PATH")
            res = subprocess.run(
                [git, *args[1:]], env=env, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE, text=True, check=False,
            )
            if res.returncode != 0:
                shutil.rmtree(dest, ignore_errors=True)
                raise RuntimeError(f"git couldn't clone repository {r['name']} from {r['url']}: {res.stderr.strip()}")
    finally:
        shutil.rmtree(home, ignore_errors=True)


def isolate(spec, cache_dir):
    """Return the run's environment, its scratch directory, and a cleanup
    function that removes the scratch directory. cache_dir holds package
    downloads across runs."""
    caller = dict(os.environ)
    env = {}
    for name in spec["pass"]:
        v = _lookup(caller, name)
        if v:
            env[name] = v

    dirs = [os.path.dirname(sys.executable)]
    missing = []
    for b in spec["binaries"]:
        p = shutil.which(b, path=_lookup(caller, "PATH") or "")
        if p:
            dirs.append(os.path.dirname(p))
        else:
            missing.append(b)
    if missing:
        raise RuntimeError("not found on PATH: " + ", ".join(missing))
    dirs += spec.get("path", [])
    if WIN:
        root = _lookup(caller, "SYSTEMROOT") or "C:\\Windows"
        dirs += [os.path.join(root, "System32"), root]
    else:
        dirs += ["/usr/bin", "/bin"]
    env["PATH"] = os.pathsep.join(dict.fromkeys(dirs))

    values, where = _secret_source(spec, caller)
    renamed = spec.get("secretEnv") or {}
    needed = sorted(set(spec["secrets"]) | set(renamed.values()))
    unset = [n for n in needed if not _lookup(values, n)]
    if unset:
        raise RuntimeError(f"secrets not set in {where}: " + ", ".join(unset))
    for n in spec["secrets"]:
        env[n] = _lookup(values, n)
    for v, n in renamed.items():
        env[v] = _lookup(values, n)

    env.update(spec["set"])

    root = tempfile.mkdtemp(prefix="solaria-run-")
    for name, rel in spec["scratch"].items():
        d = os.path.join(root, *rel.split("/"))
        os.makedirs(d, mode=0o700, exist_ok=True)
        env[name] = d
    for name, rel in spec["cache"].items():
        d = os.path.join(cache_dir, *rel.split("/"))
        os.makedirs(d, exist_ok=True)
        env[name] = d

    def cleanup():
        shutil.rmtree(root, ignore_errors=True)

    return env, root, cleanup


def adopt(env):
    """Replace this process's own environment with env, so nothing it starts
    can inherit the caller's."""
    os.environ.clear()
    os.environ.update(env)
